function filterValues(form){const values={};for(const [key,v] of new FormData(form))values[key]=values[key]?values[key]+','+v:v;return values;}
function restoreFilters(form,q){for(const el of form.elements){if(!el.name)continue;const value=q.get(el.name);if(el.multiple){const set=new Set((value||'').split(','));for(const o of el.options)o.selected=set.has(o.value);}else if(value!=null)el.value=value;}if(!form.elements.pageSize.value)form.elements.pageSize.value='10';if(!form.elements.sort.value)form.elements.sort.value='newest';}
function setupMultiFilters(form){form.querySelectorAll('[data-multi-name]').forEach(box=>{const name=box.dataset.multiName,select=form.elements[name],trigger=box.querySelector('[data-multi-toggle]'),menu=box.querySelector('.multi-menu');if(!select||!trigger)return;const sync=()=>{const selected=[...select.options].filter(o=>o.selected),checks=box.querySelectorAll('[data-multi-option]');checks.forEach(c=>c.checked=selected.some(o=>o.value===c.value));trigger.textContent=selected.length?`${box.querySelector('span').textContent}：已选 ${selected.length} 个`:`${box.querySelector('span').textContent}：全部`;};box.querySelectorAll('[data-multi-option]').forEach(c=>c.onchange=()=>{const option=[...select.options].find(o=>o.value===c.value);if(option)option.selected=c.checked;select.dispatchEvent(new Event('change',{bubbles:true}));sync();});box.querySelector('[data-multi-all]')?.addEventListener('click',()=>{[...select.options].forEach(o=>o.selected=true);select.dispatchEvent(new Event('change',{bubbles:true}));sync();});box.querySelector('[data-multi-clear]')?.addEventListener('click',()=>{[...select.options].forEach(o=>o.selected=false);select.dispatchEvent(new Event('change',{bubbles:true}));sync();});box.syncMulti=sync;trigger.onclick=e=>{e.stopPropagation();form.querySelectorAll('.multi-filter.open').forEach(x=>x!==box&&x.classList.remove('open'));box.classList.toggle('open');};sync();});if(!form.dataset.multiOutside){document.addEventListener('click',e=>{if(!e.target.closest('.multi-filter'))form.querySelectorAll('.multi-filter.open').forEach(x=>x.classList.remove('open'));});form.dataset.multiOutside='1';}}
function setDatePreset(form){const period=form.elements.period.value;if(!period||period==='custom')return;const now=new Date(),end=new Date(now),start=new Date(now);if(period==='yesterday'){start.setDate(start.getDate()-1);end.setDate(end.getDate()-1);}if(period==='week')start.setDate(start.getDate()-(start.getDay()+6)%7);if(period==='month')start.setDate(1);const day=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;form.elements.from.value=day(start);form.elements.to.value=day(end);}
