 async function load(){const current=++serial;box.setAttribute('aria-busy','true');box.innerHTML=loading();page=Math.max(1,Number(form.dataset.page)||1);const params=filterValues(form);Object.assign(params,{page,tz:Intl.DateTimeFormat().resolvedOptions().timeZone});history.replaceState({},'',location.pathname+'?'+qs(params));try{const d=await request('/api/events?'+qs({...params,...base}));if(current!==serial||!box.isConnected)return;box.removeAttribute('aria-busy');document.getElementById('event-total').textContent=`共 ${d.total||0} 条`;box.innerHTML=eventTable(d.data||[],family,d);wireEvents(box,load);}catch(e){if(current===serial&&box.isConnected){box.removeAttribute('aria-busy');box.innerHTML=uiError(e);}}}
