function coord(e){return e.x==null?'未记录':`横向：${e.x} 纵向：${e.y??'—'} 高度：${e.z??'—'}`;}
function copyCoord(e){return e.x==null?'<span class="missing">—</span>':`<button class="copy-field" data-map-event="${e.id}" data-map-position="${e.map_position||'event'}" title="在地图上查看">${esc(coord(e))}</button><button data-copy="${esc(coord(e))}" title="复制坐标">复制</button>`;}
function valueField(v,key=''){return v==null||v===''?'<span class="missing">—</span>':esc(uiText(v,key));}
function playerLink(e,target=false){const id=target?e.target_ref||e.target_steam_id:e.actor_ref||e.actor_steam_id,name=target?e.target_name:e.actor_name,char=target?e.target_char_id:e.actor_char_id;return id?`<button class="player-link" data-player="${esc(id)}" title="${esc(char?'角色编号 '+char:'查看玩家档案')}">${esc(name||'未记录')}<small>${esc(char||String(id).slice(-5))}</small></button>`:esc(name||'—')+(char?`<small>（角色 ${esc(char)}）</small>`:'');}
function metadataLabel(k){return uiLabels[k]||'附加信息';}
const weaponTypes={explosive:'爆炸物',firearm:'枪械',melee:'近战',trap:'陷阱',vehicle:'载具',environment:'环境'};
const lockNames={VeryEasy:'简易锁',Basic:'基础锁',Easy:'普通锁',Medium:'中级锁',Advanced:'高级锁',DialLock:'密码锁'};
