function durationText(n){if(n==null)return '—';const v=Math.max(0,Math.floor(Number(n)));return (v>=3600?Math.floor(v/3600)+'小时':'')+(v>=60?Math.floor(v%3600/60)+'分钟':'')+(v%60||v<60?v%60+'秒':'');}
function boolField(v,yes='是',no='否'){return v===true?yes:v===false?no:valueField(null);}
