function ownerField(m){if(m.owner_status==='system'&&/^0(?:\(|$)/.test(String(m.owner_token||m.owner_steam_id||'')))return '世界对象';const id=m.owner_ref||m.owner_steam_id;return (id?`<button class="player-link" data-player="${esc(id)}">${esc(m.owner_name||'未记录')}</button>`:esc(m.owner_name||'—'))+`<small class="identity-line">玩家编号：${esc(m.owner_steam_id||'—')} · 角色编号：${valueField(m.owner_char_id)}</small>`;}
function positionField(v,e,role='event'){if(!v)return valueField(null);return role==='copy'?`<button class="copy-field" data-copy="${esc(coord(v))}" title="复制坐标">${esc(coord(v))}</button>`:copyCoord({...v,id:e.id,map_position:role});}
function objectName(v){return !v||v==='N/A'?valueField(null):valueField(uiText(v,'target_object'));}
