function structuredCard(e,family,title,fields){return `<article class="field-card structured-card ${family}-card"><time title="${esc(fmtExact(e.ts))} · ${esc(e.ts||'')}">${fmtTime(e.ts)}</time><strong>${title}</strong><button class="icon-btn" data-event="${e.id}">查看详情</button><dl class="structured-fields">${fields.map(([label,html])=>`<div><dt>${esc(label)}</dt><dd>${html}</dd></div>`).join('')}</dl></article>`;}
