function statsPage(){return shell(`${pageTitle('运营统计','看见变化','日活、留存与热点只使用当前账号可见数据。')}<section class="filter-panel"><form id="stats-filter"><label>开始日期<input name="from" type="date"></label><label>结束日期<input name="to" type="date"></label><button class="primary">更新统计</button></form></section><div id="stats-content">${loading()}</div>`);}
async function fillStats(){const box=document.getElementById('stats-content'),form=document.getElementById('stats-filter'),params=new URLSearchParams(location.search);for(const f of form.elements)if(f.name)f.value=params.get(f.name)||'';let serial=0;const load=async()=>{const current=++serial,query=qs({...Object.fromEntries(new FormData(form)),tz:Intl.DateTimeFormat().resolvedOptions().timeZone});history.replaceState({},'','/stats?'+query);box.innerHTML=loading();try{const [t,c,h]=await Promise.all([request('/api/stats/timeline?bucket=day&'+query),request('/api/stats/coverage'),request('/api/stats/heatmap?'+query)]);if(current!==serial||!box.isConnected)return;box.innerHTML=`<section class="panel chart-panel"><div class="panel-head"><h2>每日事件量</h2><span>按可见记录统计</span></div><div id="daily-chart" class="chart"></div></section><section class="panel"><h2>各日志族解析情况</h2><div class="coverage-list">${(c.families||[]).map(f=>`<div><span>${familyNames[f.family]||'其他记录'}</span><b>${(100*f.unknown_ratio).toFixed(1)}% 其他记录</b><i><u style="width:${100*(1-f.unknown_ratio)}%"></u></i></div>`).join('')}</div></section><section class="panel"><h2>事件热点</h2><div id="heat-chart" class="chart tall"></div></section>`;uiDisposeCharts();uiChart('daily-chart',{tooltip:{trigger:'axis'},xAxis:{type:'category',data:t.data.map(x=>x.bucket)},yAxis:{type:'value'},series:[{name:'事件数量',type:'line',data:t.data.map(x=>x.count),smooth:.25}]});const days=[...new Set(h.data.map(x=>x.day))],types=[...new Set(h.data.map(x=>x.event_type))],v=getComputedStyle(document.documentElement);uiChart('heat-chart',{tooltip:{formatter:x=>`${esc(days[x.value[0]])} · ${esc(labelType(types[x.value[1]]))}：${x.value[2]} 条`},grid:{left:110,right:20,bottom:55},xAxis:{type:'category',data:days},yAxis:{type:'category',data:types.map(labelType)},visualMap:{min:0,max:Math.max(1,...h.data.map(x=>x.count)),orient:'horizontal',bottom:0,text:['多','少'],inRange:{color:[v.getPropertyValue('--bg-elevated').trim(),v.getPropertyValue('--accent').trim()]},textStyle:{color:v.getPropertyValue('--text-secondary').trim()}},series:[{type:'heatmap',data:days.flatMap((day,i)=>types.map((type,j)=>[i,j,h.data.find(x=>x.day===day&&x.event_type===type)?.count||0]))}]});}catch(e){if(box.isConnected)box.innerHTML=uiError(e);}};form.onsubmit=e=>{e.preventDefault();load();};await load();}
