 es.onmessage=e=>{if(state.onlineStream!==es)return;try{state.online=JSON.parse(e.data);state.onlineConnected=true;updateOnlinePill();if(location.pathname==='/online')uiRenderOnline();}catch{}};es.onerror=fail;
