function permissionsPage(){return shell(`${pageTitle('账号与设置','权限设置','每个勾选项独立生效；保存后该账号需要重新登录。')}<section class="panel"><label>子账号<select id="permission-user"></select></label><div id="permission-tree">${loading()}</div><button class="primary" id="save-permissions" disabled>保存权限</button><p id="permission-result" role="status"></p></section>`);}
async function fillPermissions(){const box=document.getElementById('permission-tree'),select=document.getElementById('permission-user'),save=document.getElementById('save-permissions'),result=document.getElementById('permission-result');try{const [u,p]=await Promise.all([request('/api/users'),request('/api/permissions')]);const users=u.data.filter(x=>x.role!=='super_admin'&&x.id!==state.user.id);select.innerHTML=users.map(x=>`<option value="${x.id}">${esc(x.display_name)}（${esc(x.username)}）</option>`).join('');const wanted=new URLSearchParams(location.search).get('user');if(users.some(x=>String(x.id)===wanted))select.value=wanted;const codes=p.data.filter(x=>can(x.code));const groups=[['日志类别',codes.filter(x=>x.code.startsWith('log.')&&x.code.endsWith('.view')&&x.code!=='log.raw.view')],['字段与导出',codes.filter(x=>x.code.startsWith('field.')||['log.raw.view','log.export'].includes(x.code))],['账号与系统',codes.filter(x=>!x.code.startsWith('field.')&&!x.code.startsWith('log.'))]];const load=async()=>{if(!select.value){box.innerHTML='<p class="empty">请先创建子账号。</p>';save.disabled=true;return;}const path=location.pathname==='/users'?'/users?tab=permissions&user=':'/roles?user=';history.replaceState({},'',path+select.value);const grants=await request('/api/users/'+select.value+'/permissions');box.innerHTML=groups.map(([name,items])=>`<fieldset class="permission-tree"><legend>${name}</legend><label><input type="checkbox" data-group-check>全选此组</label><div>${items.map(x=>`<label><input type="checkbox" data-permission="${esc(x.code)}" ${grants.effective.includes(x.code)?'checked':''}>${esc(x.description)}</label>`).join('')}</div></fieldset>`).join('');box.querySelectorAll('[data-group-check]').forEach(check=>{const sync=()=>{const children=[...check.closest('fieldset').querySelectorAll('[data-permission]')],n=children.filter(x=>x.checked).length;check.checked=children.length>0&&n===children.length;check.indeterminate=n>0&&n<children.length;};check.onchange=()=>check.closest('fieldset').querySelectorAll('[data-permission]').forEach(x=>x.checked=check.checked);check.closest('fieldset').querySelectorAll('[data-permission]').forEach(x=>x.onchange=sync);sync();});save.disabled=false;};select.onchange=()=>load().catch(e=>result.textContent=uiText(e.message));save.onclick=async()=>{try{save.disabled=true;await request('/api/users/'+select.value+'/permissions',{method:'PUT',body:JSON.stringify({permissions:[...box.querySelectorAll('[data-permission]')].map(x=>({code:x.dataset.permission,granted:x.checked}))})});result.textContent='权限已保存，该账号的旧登录已失效。';}catch(e){result.textContent=uiText(e.message);}finally{save.disabled=false;}};await load();}catch(e){box.innerHTML=uiError(e);}}




